"import os
import re
import sys

def process_file(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            content = f.read()

        # Replace Spanish instances
        new_content = re.sub(r'([Ll]ey de [Bb]enford)(?!\s*\(2do d\u00edgito\))', r'\1 (2do dígito)', content)

        # Replace English instances
        new_content = re.sub(r"([Bb]enford's [Ll]aw)(?!\s*\(2nd [Dd]igit\))", r'\1 (2nd Digit)', new_content)

        # Replace uppercase
        new_content = re.sub(r'(LEY DE BENFORD)(?!\s*\(2DO D\u00cdGITO\))', r'\1 (2DO DÍGITO)', new_content)

        if new_content != content:
            with open(file_path, 'w', encoding='utf-8') as f:
                f.write(new_content)
            return True
    except Exception as e:
        print(f"Error processing {file_path}: {e}")
    return False

def main(directories):
    modified_count = 0
    for directory in directories:
        for root, dirs, files in os.walk(directory):
            # skip .git
            if '.git' in dirs:
                dirs.remove('.git')

            for file in files:
                if file.endswith(('.md', '.txt', '.html', '.csv')):
                    file_path = os.path.join(root, file)
                    if process_file(file_path):
                        print(f"Modified: {file_path}")
                        modified_count += 1

    print(f"\nTotal files modified: {modified_count}")

if __name__ == '__main__':
    directories = [
        '/home/andrea-zabala-c/Desktop/ENTREGABLES_FORENSES_E14',
        '/home/andrea-zabala-c/Desktop/repo_github_comparacion'
    ]
    main(directories)
"

